import { defineConfig } from 'tsup';
import fs from 'fs';
import path from 'path';

export default defineConfig({
    entry: ['src/main.ts'],
    format: ['esm'], // пусть tsup генерит export {...}
    outDir: '../luci-app-netshift/htdocs/luci-static/resources/view/netshift',
